        "faq2Msg": "🔥 *Casa Julián Erretegia (Tolosa)*\n📍 *Helbidea:* Santa Clara Kalea, 6, 20400 Tolosa, Gipuzkoa\n\n⏰ *BAZKARIAK ETA AFARIAK:*\n• *Bazkariak:* Asteartea - Igandea 12:30 - 15:15\n• *Afariak:* Ostirala - Larunbata 20:00 - 21:30\n• *Astelehenak:* Itxita\n\n📞 *Arreta Telefonikoa:* Asteartea - Igandea 11:00 - 12:30 & 15:30 - 17:00\n📱 *WhatsApp Arreta:* Asteartea - Igandea 11:00 - 17:00\n\n🌐 *Konsultatu gure ordutegi guztiak webgune ofizialean:*\nhttps://casajulian.eus/#footer",
        "faq3Title": "3. Oporrak 2026",
        "faq3Desc": "Oporrak direla-eta itxiera datak.",
        "faq3Msg": "2026. urtean epe hauetan egongo gara itxita:\n\n- Urtarrilak 12 - Urtarrilak 29.\n- Martxoak 23 - Martxoak 20.\n- Abuztuak 24 - Irailak 8.",
        "faq4Title": "4. Ezeztapena",
        "faq4Desc": "Aurretiazko abisua eta 45€-ko kargua.",
        "faq4Msg": "Ezeztapenak gutxienez 24 ordu lehenago jakinarazi behar dira. Bestela, 45 €-ko kargua ezarriko da pertsona bakoitzeko.",
        "faq5Title": "5. Pertsona gutxitzea",
        "faq5Desc": "Erreserban pertsona kopurua txikitzea.",
