        "faq6Desc": "6 pertsona baino gehiagoko taldeak.",
        "faq6Msg": "Ez dugu 6 pertsona baino gehiagoko talderik onartzen.",
        "faq7Title": "7. Esperientzia opari",
        "faq7Desc": "Erosi Tradizio Menua 2 pertsonarentzat.",
        "faq7Msg": "2 pertsonarentzako bazkaria edo afaria opari nahi baduzu, erosi gure Tradizio Menua.",
