function getTranslation(lang, key) {
    const langCode = translations[lang] ? lang : 'es';
    if (translations[langCode] && translations[langCode][key] !== undefined) {
        return translations[langCode][key];
    }
    return translations['es'][key] || '';
}

module.exports = {
    getTranslation,
    translations
};
